  const seen = [...counts.entries()].sort((a, b) => b[1] - a[1]).map(([id, count]) => ({ id, count, pct: count / total }));
  const missing = SPEC_BIOME_IDS.filter(id => !counts.has(id));
  const audit = { seen, missing, total, spec: SPEC_BIOME_IDS };
  cache.set(key, audit);
